from fractions import Fraction
import collections

def simulate_mean_generation(m, n, max_generations=4):
    """
    Simulates the mean generation process using BFS to find if 1 is reachable 
    within max_generations. Returns (is_possible, min_depth_map).
    Assumes m and n are coprime positive integers.
    """

    initial_numbers = {
        Fraction(m, n): 0,
        Fraction(n, m): 0
    }

    queue = collections.deque()
    min_depth = initial_numbers.copy()

    for num, depth in initial_numbers.items():
        queue.append((num, depth))

    if Fraction(1) in min_depth:
        return True, min_depth

    while queue:
        x, d_x = queue.popleft()

        # Iterate over all numbers y currently known
        for y in list(min_depth.keys()):
            d_y = min_depth[y]

            # Check the depth limit before calculation to save time
            if d_x >= max_generations and d_y >= max_generations:
                continue

            # 1. Arithmetic Mean (AM)
            try:
                am = (x + y) / 2
                d_new = max(d_x, d_y) + 1

                if d_new <= max_generations:
                    if am not in min_depth or d_new < min_depth[am]:
                        min_depth[am] = d_new
                        queue.append((am, d_new))
                        if am == 1:
                            return True, min_depth
            except ZeroDivisionError:
                pass

            # 2. Harmonic Mean (HM)
            try:
                if x + y == 0: continue 
                hm = (2 * x * y) / (x + y)
                d_new = max(d_x, d_y) + 1

                if d_new <= max_generations:
                    if hm not in min_depth or d_new < min_depth[hm]:
                        min_depth[hm] = d_new
                        queue.append((hm, d_new))
                        if hm == 1:
                            return True, min_depth
            except ZeroDivisionError:
                pass

    return False, min_depth

# Test (3, 1)
m, n = 3, 1
is_possible, _ = simulate_mean_generation(m, n)
print(f"Pair ({m}, {n}): {'Possible' if is_possible else 'Not Possible'}")
